#![forbid(unsafe_code)]

//! `Builder::compile` — the documented build-script entry point — on an
//! `edition = "2023"` source.
//!
//! prost-build's code generator matches on the `syntax` string and *panics* on
//! the `"editions"` sentinel, so an edition file must never reach it. These
//! tests pin the routing: with `native-codegen` the file is generated by
//! `oxiproto-codegen`, and the emitted code must carry the resolved features.

#[cfg(all(feature = "native-parser", feature = "native-codegen"))]
mod builder_editions {
    use std::io::Write;

    /// A per-test scratch directory under `std::env::temp_dir()`, removed on drop.
    struct Scratch(std::path::PathBuf);

    impl Scratch {
        fn new(tag: &str) -> Self {
            let dir = std::env::temp_dir().join(format!(
                "oxiproto-editions-builder-{tag}-{}",
                std::process::id()
            ));
            let _ = std::fs::remove_dir_all(&dir);
            std::fs::create_dir_all(&dir).expect("scratch dir");
            Scratch(dir)
        }

        fn write_proto(&self, name: &str, body: &str) -> std::path::PathBuf {
            let path = self.0.join(name);
            let mut f = std::fs::File::create(&path).expect("create proto");
            f.write_all(body.as_bytes()).expect("write proto");
            path
        }
    }

    impl Drop for Scratch {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }

    const EDITION_PROTO: &str = r#"edition = "2023";
package edbuild;

message Inner {
  int32 x = 1;
}

message Outer {
  Inner delim = 1 [features.message_encoding = DELIMITED];
  int32 req = 2 [features.field_presence = LEGACY_REQUIRED];
  repeated int32 xs = 3 [features.repeated_field_encoding = EXPANDED];
}
"#;

    #[test]
    fn builder_generates_code_for_an_edition_file() {
        let scratch = Scratch::new("ok");
        let proto = scratch.write_proto("ed.proto", EDITION_PROTO);
        let out = scratch.0.join("out");
        std::fs::create_dir_all(&out).expect("out dir");

        oxiproto_build::Builder::new()
            .out_dir(&out)
            .compile(
                &[proto.to_string_lossy().as_ref()],
                &[scratch.0.to_string_lossy().as_ref()],
            )
            .expect("an edition file must compile through Builder::compile");

        let generated =
            std::fs::read_to_string(out.join("edbuild.rs")).expect("edbuild.rs must be generated");

        // The DELIMITED field must be a real nested message with group framing,
        // not the `String` fallback a type-unaware generator would produce.
        assert!(
            generated.contains("pub delim: Option<Box<Inner>>"),
            "DELIMITED field must generate a message type, got:\n{generated}"
        );
        assert!(
            generated.contains("WireType::SGroup") && generated.contains("WireType::EGroup"),
            "DELIMITED field must be framed by group tags"
        );
        // EXPANDED repeated encoding: one tag per element, so no packed run.
        assert!(
            generated.contains("for _v in &self.xs"),
            "EXPANDED repeated field must be emitted element-by-element"
        );
        assert!(
            generated.contains("pub struct Outer") && generated.contains("pub struct Inner"),
            "both messages must be generated"
        );
    }

    /// A plain `syntax = "proto3"` file must keep using the prost-build path —
    /// the edition routing must not capture it.
    #[test]
    fn builder_still_uses_the_prost_path_for_syntax_files() {
        let scratch = Scratch::new("proto3");
        let proto = scratch.write_proto(
            "p3.proto",
            "syntax = \"proto3\";\npackage p3build;\nmessage M { int32 a = 1; }\n",
        );
        let out = scratch.0.join("out");
        std::fs::create_dir_all(&out).expect("out dir");

        oxiproto_build::Builder::new()
            .out_dir(&out)
            .compile(
                &[proto.to_string_lossy().as_ref()],
                &[scratch.0.to_string_lossy().as_ref()],
            )
            .expect("proto3 must still compile");

        let generated =
            std::fs::read_to_string(out.join("p3build.rs")).expect("p3build.rs must be generated");
        assert!(
            generated.contains("prost::Message"),
            "proto3 output must still come from prost-build, got:\n{generated}"
        );
    }
}
